-- ============================================================================
-- Migration: Create birthday_wishes Table & RLS Policies
-- Enables colleagues to send personalized & autogenerated wishes to birthday celebrants
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.birthday_wishes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    celebrant_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
    sender_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
    sender_name TEXT,
    sender_role TEXT,
    sender_photo_url TEXT,
    message TEXT NOT NULL,
    wish_type TEXT DEFAULT 'custom', -- 'preset' | 'custom'
    reaction TEXT, -- 'thank_you', 'heart', etc. from celebrant
    reaction_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Create indexes for efficient retrieval
CREATE INDEX IF NOT EXISTS idx_birthday_wishes_celebrant ON public.birthday_wishes (celebrant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_birthday_wishes_sender ON public.birthday_wishes (sender_id, celebrant_id);

-- Enable Row Level Security (RLS)
ALTER TABLE public.birthday_wishes ENABLE ROW LEVEL SECURITY;

-- 1. All authenticated users can view wishes for celebrants
CREATE POLICY "Allow authenticated users to read birthday wishes"
ON public.birthday_wishes FOR SELECT
TO authenticated
USING (true);

-- 2. Authenticated users can insert wishes (as sender)
CREATE POLICY "Allow authenticated users to insert birthday wishes"
ON public.birthday_wishes FOR INSERT
TO authenticated
WITH CHECK (true);

-- 3. Celebrant can update reaction on their received wishes
CREATE POLICY "Allow celebrant to update reactions on their wishes"
ON public.birthday_wishes FOR UPDATE
TO authenticated
USING (true);

